const assert = require('node:assert/strict');
const evaluate = require('./evaluate.cjs');
const comment = {id:1,user:{login:'security',type:'User'},body:'/approve-policy abc',created_at:'2026-01-01T10:00:00Z',updated_at:'2026-01-01T10:00:00Z'};
const review = {id:2,user:{login:'reviewer',type:'User'},state:'APPROVED',commit_id:'abc',submitted_at:'2026-01-01T10:01:00Z'};
const base = {sha:'abc',author:'author',comments:[comment],reviews:[review],policyUsers:['security'],prUsers:['reviewer']};
assert.equal(evaluate(base).state,'success');
assert.equal(evaluate({...base,comments:[]}).state,'pending');
assert.equal(evaluate({...base,sha:'new'}).state,'pending');
assert.equal(evaluate({...base,reviews:[{...review,submitted_at:'2026-01-01T09:59:00Z'}]}).state,'pending');
assert.equal(evaluate({...base,comments:[{...comment,updated_at:'2026-01-01T10:02:00Z'}]}).state,'pending');
assert.equal(evaluate({...base,author:'security'}).state,'pending');
assert.equal(evaluate({...base,prUsers:['security'],reviews:[{...review,user:comment.user}]}).state,'pending');
assert.equal(evaluate({...base,reviews:[review,{...review,id:3,state:'DISMISSED'}]}).state,'pending');
assert.equal(evaluate({...base,reviews:[review,{...review,id:3,state:'CHANGES_REQUESTED'}]}).state,'failure');
assert.equal(evaluate({...base,reviews:[{...review,commit_id:'old'}]}).state,'pending');
console.log('10 approval ordering scenarios passed');
